INSERT INTO `conversation_messages` (`id`, `conversation_id`, `role`, `content`, `message_type`, `created_at`) VALUES
('0218b1d5-bb27-5a01-8c57-4b58773e3b49', '26ad7b2e-f449-5e71-aae5-b3033ed4f6bf', 'user', '3 BHK', 'voice:000000007', '2026-10-31 09:58:23'),
('06b167bb-ac9a-475c-ad1d-918b5e415171', 'e584f95f-b656-4316-ac80-0d0138a4ec05', 'assistant', 'Seri sir, puriyudhu. Naan onnu kekkalam... unga friends or family-la Dubai property pathi interest irukkanga? Referral irundha naan direct-ah pesuvom.', 'text', '2026-10-31 05:22:53'),
('09dbbf10-10ac-53a5-8e9d-ce3c37818b92', '26ad7b2e-f449-5e71-aae5-b3033ed4f6bf', 'user', 'வணக்கம் பிரியா, என் பெயர் மோகன். நீங்க எப்படி இருக்கீங்க?', 'voice:000000002', '2026-10-31 09:57:44'),
('0a6d7b10-1160-45db-a069-a44098b91311', 'b13566d2-1c41-403c-b130-a2a4c78fc11e', 'assistant', 'Sorry sir, naan Lyka Realty AI assistant. Personal relationship illa. Property pathi pesalaam.', 'text', '2026-10-31 05:26:08'),
('0cd93647-aa9c-4246-8ed2-2a39fb38e9d8', 'b13566d2-1c41-403c-b130-a2a4c78fc11e', 'assistant', 'Sollunga sir. Neenga investment-ku paakureengala, illa family-ku own use-ah sir?', 'text', '2026-10-31 05:25:55'),
('0d2d3cca-972f-5918-96f0-92737e9f9471', '26ad7b2e-f449-5e71-aae5-b3033ed4f6bf', 'assistant', 'Seri sir. Namma', 'voice:000000016', '2026-10-31 09:59:22'),
('0e1790f1-f56a-5337-8bca-b7ff66918190', 'be0003fa-0b1f-5cc8-9075-8f94a44e82b4', 'user', '75 lakh.', 'voice:000000003', '2026-10-31 05:43:25'),
('0f2dd7bd-dcdb-5523-b2af-959a9ca602fb', '26ad7b2e-f449-5e71-aae5-b3033ed4f6bf', 'assistant', 'Downtown Dubai or Business Bay side-la paakkalaam sir. Ithu central-la irukkum, public places-kku easy access kooda irukkum. Nalla value-va irukkum.', 'voice:000000011', '2026-10-31 09:58:47'),
('15a0063c-17dd-5d56-84ce-d9830b20eb34', '26ad7b2e-f449-5e71-aae5-b3033ed4f6bf', 'assistant', 'Seri sir. Ungalukku follow-up Phone-la venuma, WhatsApp-la venuma, illa Email prefer panreengala?', 'voice:000000013', '2026-10-31 09:59:00'),
('1955b008-b6ba-4e4d-90a8-6cee39acc43e', '8fd0f993-fce6-4edf-8393-cff9f43d47a4', 'user', 'MOHAN', 'text', '2026-10-11 15:25:44'),
('1c92fa4e-53ce-5c7d-b14c-406c94e3f98b', 'be0003fa-0b1f-5cc8-9075-8f94a44e82b4', 'user', 'I want an OMR apartment.', 'voice:000000001', '2026-10-31 05:43:25'),
('2344e030-e5f8-5b64-bef2-db5e273d5188', 'bd66d36a-f55e-5d13-a80a-686d8f56c213', 'assistant', 'I can help with property enquiries.', 'voice:000000002', '2026-10-31 08:09:38'),
