('5ee88660-7c49-4e52-8791-5a44aaa32a31', 'e584f95f-b656-4316-ac80-0d0138a4ec05', 'assistant', 'Hello sir! Eppadi irukkeenga? Naan Priya, Lyka Realty-la irundhu pesuren.', 'text', '2026-10-31 05:22:14'),
('6011e729-f7a4-4aaf-aebf-09cd4fda58e1', 'b13566d2-1c41-403c-b130-a2a4c78fc11e', 'assistant', 'Ungala correct-ah address panna mattum thaan sir. Unga details note pannikitta, senior team member ungalukku help panna easy-a irukkum.', 'text', '2026-10-31 05:25:35'),
('642e017f-bd8b-5190-8252-de8535f40d0e', '0a6aa836-dee2-59f0-bfb1-b2e81ab4e0ed', 'user', 'Chennai-la 3BHK flat budget 1.5 Cr, CMDA approved venum.', 'voice:000000006', '2026-10-31 07:10:55'),
